:host{--navy:#061734;--navy2:#031c40;--cyan:#21bee7;--blue:#0a64bb;--ink:#061b42;--soft:#eaf4ff;--light:#f5f7fb;--line:#e4eaf1;--muted:#53657b;--shadow:0 18px 45px rgba(15,40,80,.16);font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Inter,system-ui,sans-serif;color:var(--ink)}
