.desktop-hero{height:344px;display:grid;grid-template-columns:46% 54%;position:relative;background:linear-gradient(110deg,#f0f5fb,#cbdff3)}.desktop-hero-copy{padding:52px 0 30px 36px;z-index:2}.desktop-hero h2{font-size:clamp(28px,2.72vw,40px);line-height:1.065;letter-spacing:-1.5px;max-width:380px;font-weight:820;color:#041c42}.desktop-hero p{font-size:14px;line-height:1.45;max-width:340px;color:#25354c;margin-top:15px}.hero-actions{display:flex;gap:10px;align-items:center;margin-top:17px}.actionprimary,.actionsecondary{height:43px;border-radius:11px;padding:0 17px;display:inline-flex;gap:11px;align-items:center;justify-content:center;font-size:12px;font-weight:750;white-space:nowrap}.actionprimary{background:#072c85;color:#fff;border:1px solid #072c85}.actionsecondary{background:#fff;color:#08285f;border:1px solid #1c488f}.actionprimary:hover{background:#0644a3}.actionsecondary:hover{background:#eaf7ff}.desktop-hero-art{background:linear-gradient(125deg,#eaf1f9,#087dbf 80%,#032654);overflow:hidden;height:100%;position:relative}.desktop-hero-art img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:52% center}.desktop-hero-art:before{content:"";position:absolute;inset:0;background:linear-gradient(90deg,#e5edf8 0%,transparent 14%);z-index:1;pointer-events:none}.dots{display:flex;gap:6px;align-items:center;justify-content:center}.dots button{width:9px;height:9px;background:#bfc8d5;border:0;border-radius:50%;padding:0}.dots button.active{background:#062d80}.hero-dots-desktop{position:absolute;left:48%;bottom:11px;z-index:3}
.promo-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:13px;padding:14px 20px 16px}.promo{height:131px;border-radius:14px;overflow:hidden;position:relative;border:0;text-align:left;background:linear-gradient(120deg,#e8f4ff,#cee8ff);padding:17px 14px 12px 17px;color:#061c3e}.promo.pale{background:linear-gradient(120deg,#f1f0f0,#e5e6e8)}.promo.sky{background:linear-gradient(125deg,#e6f4ff,#c3e2fe)}.promo .copy{z-index:2;position:relative;max-width:56%;display:flex;flex-direction:column;height:100%}.promo h3{font-size:16px;line-height:1.13;letter-spacing:-.4px}.promo p{font-size:11px;line-height:1.35;margin-top:7px;color:#28415c}.promo .link{display:flex;gap:4px;align-items:center;margin-top:auto;font-size:11px;font-weight:770}.promo img{position:absolute;right:-6%;bottom:-12%;width:51%;height:116%;object-fit:contain;mix-blend-mode:multiply}.promo.sky img{right:-11%;width:62%;height:92%;bottom:-2%}
.products-area{padding:0 20px 18px}.sectionheader{display:flex;justify-content:space-between;align-items:center;margin:7px 0 13px}.sectionheader h2{font-size:20px;font-weight:800;letter-spacing:-.55px}.text-link{border:0;background:transparent;color:#045fbe;display:flex;gap:4px;align-items:center;font-size:11px;font-weight:750;white-space:nowrap;padding:6px}.product-and-help{display:grid;grid-template-columns:minmax(0,5fr) minmax(128px,1.07fr);gap:12px}.product-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:9px}.product{background:white;border:1px solid #e3eaf2;border-radius:14px;min-width:0;overflow:hidden;display:flex;flex-direction:column;position:relative;box-shadow:0 6px 14px #12334f0b}.product .image{height:111px;display:grid;place-items:center;padding:8px 8px 0;position:relative}.product .image img{max-width:100%;max-height:93%;object-fit:contain}.heart{position:absolute;right:4px;top:5px;border:0;border-radius:50%;background:#ffffffb8;width:26px;height:26px;color:#15324d;display:grid;place-items:center}.heart[aria-pressed="true"]{color:#d01f59}.heart[aria-pressed="true"] svg{fill:#ffd6e5}.product-body{padding:3px 10px 11px;display:flex;flex:1;flex-direction:column}.product h3{font-size:11px;line-height:1.25;letter-spacing:-.1px;font-weight:600;min-height:28px}.product .price{font-size:15px;letter-spacing:-.4px;font-weight:830;margin:6px 0 7px;white-space:nowrap}.stock{display:flex;gap:5px;align-items:center;color:#126a43;font-size:10px;white-space:nowrap}.stock .icon{height:14px;width:14px}.support-stack{display:grid;grid-template-rows:1fr 1fr;gap:9px}.support-tile{border-radius:14px;border:0;padding:12px 9px;display:grid;grid-template-columns:33px minmax(0,1fr) 11px;gap:5px;align-items:center;text-align:left;color:#0a2753;background:#e8f3ff}.support-tile.whatsapp{background:#e5f9f3}.support-tile strong{font-size:12px}.support-tile p{font-size:10px;line-height:1.3;margin-top:6px}.support-tile .symbol{font-size:28px;color:#14bdef}.support-tile.whatsapp .symbol{color:#0dab5a}.demo-foot{color:#536d82;font-size:9px;text-align:center;padding:7px 12px;background:#f8fbff;border-top:1px solid #ebf1f6}
.phone{width:350px;position:relative;height:848px}.phone-device{width:320px;transform:scale(1.09375);transform-origin:top left;background:linear-gradient(120deg,#13191f,#3e464d 25%,#070d12 41%,#171a1e 80%,#4b555d);border:2px solid #777e88;box-shadow:0 18px 45px #0a203d3d;border-radius:47px;padding:9px;min-height:779px;position:relative}.phone-device:before{content:"";position:absolute;inset:3px;border:2px solid #000;border-radius:43px;pointer-events:none;z-index:10}.phone-screen{height:755px;background:#fff;overflow:hidden;position:relative;border-radius:37px;display:flex;flex-direction:column;color:var(--ink)}.phone-status{background:#001637;color:#fff;height:28px;display:flex;align-items:center;justify-content:space-between;padding:9px 21px 0;font-size:10px;font-weight:650;position:relative}.island{background:black;border-radius:999px;width:89px;height:19px;position:absolute;left:50%;top:6px;transform:translateX(-50%)}.phone-status svg{width:12px;height:12px}.status-right{display:flex;gap:3px;align-items:center}.mobile-head{background:#001637;display:flex;align-items:center;justify-content:space-between;height:45px;padding:0 12px;color:#fff;flex-shrink:0}.mobile-head .brand{width:135px;height:49px}.mobile-head .brand img{width:135px;height:47px}.mobile-controls{display:flex;align-items:center;gap:5px}.mobile-controls button{color:#fff;background:transparent;border:0;display:grid;place-items:center;width:29px;height:33px;position:relative}.mobile-controls .icon{height:21px;width:21px}.mobile-controls .badgecount{right:-2px;top:1px}.mob-searchwrap{background:#001637;padding:0 10px 8px}.mob-searchwrap .search{height:38px;border-radius:12px;gap:8px;padding:0 10px}.mob-searchwrap .search input{font-size:10px}.mob-searchwrap .search .icon{width:18px;height:18px}
.phone-content{min-height:0;flex:1;overflow-y:auto;overflow-x:hidden;scrollbar-width:none;background:#fff}.phone-content::-webkit-scrollbar{display:none}.mobile-category{height:82px;padding:8px 8px 7px;background:white;display:grid;grid-template-columns:repeat(5,1fr);gap:4px;border-radius:14px 14px 0 0}.mobile-category button{border:0;background:white;display:flex;flex-direction:column;align-items:center;gap:4px;justify-content:start;font-size:9px;color:#07244b;font-weight:700;padding:0}.mobile-category button .cat-icon{background:#e8f2ff;border-radius:12px;display:grid;place-items:center;width:40px;height:39px;flex:none}.mobile-category button .icon{height:22px;width:22px}.mobile-category button.active .cat-icon{box-shadow:inset 0 0 0 2px #2eacd4;background:#def7ff}
.mobile-hero{margin:1px 7px 4px;border-radius:18px;background:linear-gradient(140deg,#051e48,#06417a 65%,#0b86c6);height:239px;overflow:hidden;position:relative;color:#fff;flex-shrink:0}.mobile-hero:before{content:"";position:absolute;right:-40px;top:-65px;width:155px;height:232px;border-radius:55%;background:linear-gradient(140deg,#008dd0,#073b82);transform:rotate(27deg);opacity:.7}.mobile-hero .mobile-hero-copy{position:relative;z-index:2;padding:14px 17px 0}.mobile-hero h2{font-size:21px;line-height:1.05;letter-spacing:-.8px;max-width:230px}.mobile-hero p{font-size:10px;line-height:1.45;margin-top:7px}.mobile-hero .actionsecondary{height:31px;font-size:10px;margin-top:10px;border:0;border-radius:10px;padding:0 11px}.mobile-hero .hero-image{position:absolute;left:0;bottom:0;width:100%;height:106px;object-fit:cover;object-position:50% 52%;mix-blend-mode:normal}.mobile-hero-dots{position:absolute;left:50%;bottom:7px;transform:translateX(-50%);z-index:3}.mobile-hero-dots button{width:7px;height:7px;background:#91b3d6}.mobile-hero-dots button.active{background:#071f58}
.mobile-section{padding:5px 10px 0}.mobile-section .sectionheader{margin:7px 0 10px}.mobile-section .sectionheader h2{font-size:16px;letter-spacing:-.4px}.mobile-section .sectionheader .text-link{font-size:10px}.mobile-products{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:5px}.mobile-product{min-height:162px;border:1px solid #edf1f5;border-radius:12px;overflow:hidden;position:relative;display:flex;flex-direction:column;min-width:0;box-shadow:0 4px 12px #152e5012;background:#fff}.mobile-product img{height:74px;width:100%;object-fit:contain;padding:9px 7px 2px}.mobile-product .heart{top:1px;right:2px;width:21px;height:21px}.mobile-product .heart .icon{width:14px;height:14px}.mobile-product .info{padding:4px 6px 9px;flex:1;display:flex;flex-direction:column}.mobile-product .name{font-size:9px;line-height:1.2;min-height:27px;font-weight:650}.mobile-product .price{font-size:11px;font-weight:830;white-space:nowrap;margin-top:auto}.mobile-cta{padding:12px 11px 18px}.mobile-cta button{width:100%;background:#eef7ff;border:1px solid #d9edf9;color:#052c58;border-radius:12px;padding:11px;display:flex;align-items:center;justify-content:space-between;font-weight:700;font-size:11px}
.mobile-bottom{height:68px;background:#fff;border-top:1px solid #e6edf3;display:grid;grid-template-columns:repeat(4,1fr);flex-shrink:0;padding:5px 6px 14px}.mobile-bottom button{display:flex;flex-direction:column;justify-content:center;align-items:center;gap:4px;background:transparent;border:0;color:#182a40;position:relative;font-size:10px;padding:0;font-weight:550}.mobile-bottom button.active{color:#1262ca;font-weight:750}.mobile-bottom .icon{width:22px;height:22px}.mobile-bottom .badgecount{right:20px;top:1px}.home-indicator{position:absolute;width:102px;height:4px;background:#121212;bottom:7px;left:50%;transform:translateX(-50%);border-radius:8px;z-index:6}
.drawer-backdrop{position:fixed;inset:0;background:#061b37a8;z-index:100;display:none;align-items:center;justify-content:center;padding:20px}.drawer-backdrop.open{display:flex}.dialog{width:min(450px,98vw);background:white;border-radius:22px;overflow:hidden;box-shadow:0 24px 75px #020d2799;padding:24px;max-height:calc(var(--home-height) * 0.9);overflow-y:auto}.dialog-head{display:flex;align-items:center;justify-content:space-between;gap:15px}.dialog-head h2{font-size:20px}.x-button{border:0;background:#edf4fa;border-radius:11px;width:37px;height:37px;display:grid;place-items:center}.dialog-desc{font-size:13px;line-height:1.55;color:#53657a;margin-top:12px}.dialog-footer{font-size:11px;color:#2e5e80;background:#ecf6fc;border-radius:11px;padding:13px;margin-top:14px}.dialog-products{display:grid;gap:9px;margin-top:13px}.dialog-products .line{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:10px;border:1px solid #e4edf5;border-radius:11px;font-size:13px}.dialog-products .line button{background:#e8f4fc;color:#003f71;border:0;border-radius:8px;padding:7px}.reference-img{width:100%;border:1px solid #dce8f3;border-radius:11px;margin-top:12px}
.review-info{max-width:1400px;margin:18px auto 0;display:flex;justify-content:space-between;gap:16px;align-items:center;color:#526986;font-size:12px}.review-info b{color:#18395c}.statusline{min-height:22px;color:#2b7097;font-size:11px;text-align:center;margin-top:6px}.sr-only{position:absolute!important;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}
@media(max-width:1090px){.stage{grid-template-columns:minmax(480px,1fr) 290px;gap:12px}.phone{width:290px;height:648px}.phone-device{transform:scale(.90625);transform-origin:top left;width:320px}.phone{height:648px}.utility{font-size:9px;padding:0 14px}.mainbar{padding:0 14px;grid-template-columns:170px minmax(90px,1fr) 170px}.desktop-nav{padding:0 12px}.desktop-nav button{font-size:10px;gap:3px}.desktop-hero h2{font-size:30px}.desktop-hero-copy{padding-left:22px}.promo h3{font-size:13px}.product h3{font-size:9px}.product .price{font-size:12px}}
@media(max-width:830px){.stage{grid-template-columns:1fr}.desk{display:none}.phone{width:320px;margin:auto}.shell{padding:13px 8px}.shell-head{padding:0 8px}.stage.only-desktop{grid-template-columns:1fr}.stage.only-desktop .desk{display:block}.stage.only-phone{grid-template-columns:1fr}.stage.only-phone .phone{width:320px;height:auto}.stage.only-phone .phone-device{transform:none}.stage.only-phone .phone{height:auto}.stage.only-phone .phone-screen{height:755px}.phone-device{transform:none}.phone{height:auto;width:320px}.review-info{padding:0 12px;flex-wrap:wrap}}
