.shell-head,.review-info,.review-panel,.demo-gallery-instructions,.statusline{display:none!important}.shell{padding:0!important;max-width:none}.stage{margin:0 auto}.stage.only-desktop{max-width:1140px}.stage.only-desktop .desk{box-shadow:none}.stage.only-phone{display:block!important;width:100%;min-width:0}.stage.only-phone .phone{margin:auto;width:min(100%,390px)!important;max-width:390px;min-width:0;height:auto!important}.stage.only-phone .phone-device{width:100%!important;max-width:100%;min-width:0;transform:none;min-height:0!important;height:auto!important}.stage.only-phone .phone-screen{width:100%;min-width:0;max-width:100%;height:calc(var(--home-height) - 24px)!important;min-height:0!important}@media(max-width:600px){.stage.only-phone .phone-device{padding:0!important;border:0!important;border-radius:0!important;background:none;box-shadow:none}.stage.only-phone .phone-screen{height:var(--home-height)!important;border-radius:0!important}.stage.only-phone .phone-status{display:none}.stage.only-phone .phone{width:100%!important}.stage.only-phone{max-width:none!important}}.crumb [data-integration-home],.mobile-crumb [data-integration-home]{cursor:pointer;text-decoration:underline;text-underline-offset:3px}

