/* Mobile floating glass navigation — scoped to the iPhone shell only. */
.stage.only-phone .phone-screen {
  --dock-height: 66px;
  --dock-bottom: max(10px, env(safe-area-inset-bottom, 0px));
  --dock-reserve: calc(var(--dock-height) + var(--dock-bottom) + 12px);
}
.stage.only-phone .phone-screen > .phone-content {
  padding-bottom: var(--dock-reserve);
  scroll-padding-bottom: var(--dock-reserve);
}
.stage.only-phone .phone-screen > .mobile-bottom {
  position: absolute;
  left: max(14px, env(safe-area-inset-left, 0px));
  right: max(14px, env(safe-area-inset-right, 0px));
  bottom: var(--dock-bottom);
  height: var(--dock-height);
  z-index: 20;
  grid-template-columns: repeat(3, minmax(0,1fr));
  gap: 4px;
  padding: 5px;
  border: 1px solid rgba(255,255,255,.88);
  border-radius: 36px;
  background: rgba(243,248,255,.76);
  -webkit-backdrop-filter: blur(24px) saturate(155%);
  backdrop-filter: blur(24px) saturate(155%);
  box-shadow: 0 9px 26px rgba(6,23,52,.19), inset 0 1px 1px rgba(255,255,255,.9), 0 0 0 1px rgba(6,23,52,.05);
}
.stage.only-phone .mobile-bottom button {
  min-width: 0;
  min-height: 44px;
  border-radius: 28px;
  font-size: 11px;
  gap: 4px;
  color: #182a40;
}
.stage.only-phone .mobile-bottom button.active {
  color: #075bbb;
  background: rgba(255,255,255,.54);
  box-shadow: inset 0 1px 1px rgba(255,255,255,.8);
}
.stage.only-phone .mobile-bottom button:focus-visible {
  outline: 2px solid #075bbb;
  outline-offset: -3px;
}
.stage.only-phone .mobile-bottom .badgecount { top: 2px; right: max(8px, calc(50% - 35px)); }
@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
  .stage.only-phone .phone-screen > .mobile-bottom { background: #edf4fc; }
}
@media (prefers-reduced-transparency: reduce) {
  .stage.only-phone .phone-screen > .mobile-bottom { background: #edf4fc; -webkit-backdrop-filter: none; backdrop-filter: none; }
}

.stage.only-phone .phone-content > .mobile-hero { margin-top: 10px; }

/* iPhone native document scrolling — browser chrome controls the visible viewport. */
@media (max-width:830px) {
  :host { display:block; }
  .stage.only-phone .phone-device { transform:none; border:0!important; border-radius:0!important; padding:0!important; box-shadow:none; background:none; }
  .stage.only-phone .phone-screen { height:auto!important; min-height:100vh!important; min-height:100dvh!important; overflow:visible; border-radius:0!important; }
  .stage.only-phone .phone-screen > .phone-content { flex:1 0 auto; overflow:visible; min-height:0; padding-bottom:var(--dock-reserve); }
  .stage.only-phone .phone-screen > .mobile-head { position:sticky; top:0; height:52px; min-height:52px; z-index:30; }
  .stage.only-phone .phone-screen > .mob-searchwrap { position:sticky; top:52px; z-index:29; }
  .stage.only-phone .phone-screen > .mobile-bottom { position:fixed; }
}

@media(max-width:830px){.home-viewport {height:auto;overflow:visible;} .home-body {min-height:100vh;min-height:100dvh;} }
